/**
 * R2 against its oracle: the `compat.qnt` traces committed under `__fixtures__/diff/traces/`,
 * generated by `.sdlc/intents/apicontract-diff/compat-traces.qnt` (no Quint at test time). Each
 * state is an (old, new) pair of versions, a version being what its sender emits (`s`) and what its
 * receiver accepts (`r`) as sets of values, with the verdicts Quint computed for the pair.
 */
import { readdirSync, readFileSync } from 'node:fs';

import { describe, expect, it } from 'vitest';

import { DIRECTIONS, type Direction } from './core/model.js';
import { classify, MODES, payloadRules, SIDES } from './diff-classify.js';
import { compareSchemas } from './diff-schema.js';

interface ItfSet {
  readonly '#set': readonly { readonly '#bigint': string }[];
}
interface ItfVer {
  readonly s: ItfSet;
  readonly r: ItfSet;
}
interface State {
  readonly old: ItfVer;
  readonly nu: ItfVer;
  readonly verdict: { readonly backward: boolean; readonly forward: boolean; readonly full: boolean };
}

const TRACES = new URL('__fixtures__/diff/traces/', import.meta.url);
const states: State[] = readdirSync(TRACES)
  .filter((name) => name.endsWith('.itf.json'))
  .flatMap((name) => (JSON.parse(readFileSync(new URL(name, TRACES), 'utf8')) as { states: State[] }).states);

const values = (set: ItfSet): number[] => set['#set'].map((v) => Number(v['#bigint']));
const schema = (set: ItfSet) => ({ enum: values(set) });
const same = (v: ItfVer): boolean => values(v.s).join() === values(v.r).join();

/** Whether every value `sender` emits, `receiver` accepts, read off `compareSchemas` alone. */
const accepts = (sender: ItfSet, receiver: ItfSet): boolean =>
  !compareSchemas(schema(sender), schema(receiver), 'request').some((change) => change.effect === 'narrows');

describe('the committed compat.qnt traces', () => {
  it('are enough to mean something: 24 traces, both verdicts of each rule, and single-schema pairs', () => {
    expect(readdirSync(TRACES).filter((name) => name.endsWith('.itf.json'))).toHaveLength(24);
    expect(states).toHaveLength(384);
    for (const rule of ['backward', 'forward', 'full'] as const) {
      expect(new Set(states.map((state) => state.verdict[rule]))).toEqual(new Set([true, false]));
    }
    expect(states.filter((state) => same(state.old) && same(state.nu)).length).toBeGreaterThan(20);
  });

  it.each(states.map((state, index) => [index, state] as const))('state %i: compareSchemas reads BACKWARD and FORWARD as Quint does', (_index, state) => {
    expect(accepts(state.old.s, state.nu.r)).toBe(state.verdict.backward);
    expect(accepts(state.nu.s, state.old.r)).toBe(state.verdict.forward);
  });
});

/** The pairs where each version is one schema, as a contract's payload is: what is sent is what is accepted. */
const single = states.filter((state) => same(state.old) && same(state.nu));
const QUESTIONS = DIRECTIONS.flatMap((direction) => MODES.flatMap((mode) => SIDES.map((side) => [direction, mode, side] as const)));

describe('classify agrees with compat.qnt on every single-schema trace', () => {
  it.each(QUESTIONS)('%s, --mode %s, --side %s', (direction, mode, side) => {
    for (const state of single) {
      const changes = compareSchemas(schema(state.old.r), schema(state.nu.r), direction);
      const breaking = changes.some((change) => classify(change, direction, mode, side) === 'breaking');
      const holds = payloadRules(direction, mode, side).every((rule) => state.verdict[rule]);
      expect(breaking, JSON.stringify(state)).toBe(!holds);
    }
  });

  it('reversing a diff swaps backward and forward (reversalSwaps)', () => {
    for (const state of single) {
      for (const direction of DIRECTIONS) {
        const breaks = (a: ItfSet, b: ItfSet, mode: 'backward' | 'forward'): boolean =>
          compareSchemas(schema(a), schema(b), direction).some((change) => classify(change, direction, mode, 'caller') === 'breaking');
        expect(breaks(state.old.r, state.nu.r, 'backward')).toBe(breaks(state.nu.r, state.old.r, 'forward'));
      }
    }
  });
});

describe('payloadRules', () => {
  it.each([
    // oasdiff's question: old callers, new server. A request must accept what it accepted; a response must not send more.
    ['request', 'backward', 'caller', ['backward']],
    ['response', 'backward', 'caller', ['forward']],
    ['request', 'forward', 'caller', ['forward']],
    ['response', 'forward', 'caller', ['backward']],
    ['request', 'backward', 'server', ['forward']],
    ['response', 'backward', 'server', ['backward']],
    ['tool-call', 'backward', 'caller', ['backward']],
    ['tool-result', 'backward', 'caller', ['forward']],
    ['subscribe', 'backward', 'caller', ['backward']],
    ['publish', 'backward', 'caller', ['forward']],
    ['argv', 'backward', 'caller', ['backward']],
    ['request', 'full', 'caller', ['backward', 'forward']],
    ['response', 'full', 'server', ['backward', 'forward']],
  ] as const)('%s under --mode %s --side %s keeps %j', (direction: Direction, mode, side, rules) => {
    expect(payloadRules(direction, mode, side)).toEqual(rules);
  });
});

describe('classify', () => {
  it.each([
    ['narrows', 'request', 'breaking'],
    ['widens', 'request', 'non-breaking'],
    ['narrows', 'response', 'non-breaking'],
    ['widens', 'response', 'breaking'],
    ['unknown', 'request', 'unknown'],
    ['neutral', 'response', 'non-breaking'],
  ] as const)('a change that %s a %s is %s for old callers', (effect, direction, verdict) => {
    expect(classify({ effect }, direction, 'backward', 'caller')).toBe(verdict);
  });

  it('under full, either effect breaks a payload', () => {
    expect(classify({ effect: 'widens' }, 'request', 'full', 'caller')).toBe('breaking');
    expect(classify({ effect: 'narrows' }, 'request', 'full', 'caller')).toBe('breaking');
    expect(classify({ effect: 'neutral' }, 'request', 'full', 'caller')).toBe('non-breaking');
  });
});
